 fig.tight_layout(rect=(.01,.055,1,.87));accuracy=OUT/'benchmark-overnight-v1-accuracy.png';fig.savefig(accuracy,dpi=300);fig.savefig(accuracy.with_suffix('.pdf'));plt.close(fig)
 runtimekeys=['released-arrmes','qwen-base','functiongemma-base','granite350m','granite-bf16','qwen1.7b','qwen4b','portable-public-f16-cpu','portable-public-q4-cpu']
 runtime=[(k,load(k)) for k in runtimekeys if load(k)]
 fig,(ax,mem)=plt.subplots(1,2,figsize=(14,7.2),gridspec_kw={'width_ratios':[1.2,1]})
 yy=np.arange(len(runtime));p50=[d['summary']['warm_routing_wall']['p50_seconds']*1000 for _,d in runtime];p95=[d['summary']['warm_routing_wall']['p95_seconds']*1000 for _,d in runtime]
 for i,(a,b) in enumerate(zip(p50,p95)):ax.plot([a,b],[i,i],color='#94a3b8',lw=3)
 ax.scatter(p50,yy,color='#0f766e',s=55,label='Warm p50',zorder=3);ax.scatter(p95,yy,color='#4338ca',s=42,marker='D',label='Warm p95',zorder=3)
 ax.set_yticks(yy);ax.set_yticklabels([NAMES[k] for k,_ in runtime],fontsize=10);ax.invert_yaxis();ax.set_xlabel('Inclusive route wall time (milliseconds)');ax.set_title('Routing includes prompt, inference and verification',loc='left',fontsize=12);ax.grid(axis='x',alpha=.15);ax.legend(frameon=False,loc='lower right')
 weight=[sum(a['bytes'] for a in d.get('artifacts',[]) if a['file'].endswith(('.safetensors','.gguf')))/1024**2 for _,d in runtime]
 parent=[(d['summary']['peak_process_rss_bytes'] or float('nan'))/1024**2 for _,d in runtime]
 child=[(d['summary'].get('native_child_peak_rss_bytes') or d['summary'].get('sampled_peak_native_child_rss_bytes') or 0)/1024**2 for _,d in runtime]
 mem.barh(yy-.2,weight,height=.2,label='Weight files',color='#94a3b8');mem.barh(yy,parent,height=.2,label='Python process peak RSS',color='#0f766e');mem.barh(yy+.2,child,height=.2,label='Native child RSS*',color='#4338ca');mem.set_yticks(yy);mem.set_yticklabels([]);mem.invert_yaxis();mem.set_xlabel('MiB (counters overlap; do not add)');mem.set_title('Files do not equal runtime RAM',loc='left',fontsize=12);mem.grid(axis='x',alpha=.15);mem.legend(frameon=False,loc='lower right',fontsize=9)
 fig.suptitle('Latency and memory: measured on the same Mac',x=.02,y=.98,ha='left',fontsize=22,fontweight='bold');fig.text(.02,.91,'MLX uses Apple GPU/unified memory; GGUF rows use four ARM64 CPU threads. These are different backends, not a CPU-only model race.',fontsize=10)
 fig.text(.02,.02,'* Native child RSS is sampled lower-bound in initial runs; final-source reruns also record OS reaped-child high-water RSS. MLX allocation peaks are separate in raw receipts.',fontsize=9,color='#475569');fig.tight_layout(rect=(.01,.055,1,.87));latency=OUT/'benchmark-overnight-v1-runtime.png';fig.savefig(latency,dpi=300);fig.savefig(latency.with_suffix('.pdf'));plt.close(fig)
 summaries=[]
 for key in NAMES:
  d=load(key)
  if not d or 'unique_cases' not in d.get('summary',{}):continue
  s=d['summary'];rows=[r for r in d['rows'] if r['repetition']==0]
  repcounts={str(rep):{'raw_exact':sum(r['track_A']['arguments_and_entities_exact'] for r in d['rows'] if r['repetition']==rep),'verified_exact':sum(r['track_B']['verified_exact'] for r in d['rows'] if r['repetition']==rep)} for rep in sorted({r['repetition'] for r in d['rows']})}
  summaries.append({'key':key,'label':NAMES[key],**s,'per_repetition_accuracy':repcounts})
 summary={'schema_version':1,'generated_at':datetime.now(timezone.utc).isoformat(),'dataset_sha256':load('released-arrmes')['dataset_sha256'],'results':summaries,
          'exploratory_paired_comparisons':{'public_vs_qwen4b_translated':paired(load('released-arrmes'),load('qwen4b'),'translated_arguments_and_entities_exact'),'public_vs_untuned_base_translated':paired(load('released-arrmes'),load('qwen-base'),'translated_arguments_and_entities_exact')}}
 (DATA/'comparison-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
 with (DATA/'comparison-summary.csv').open('w',newline='') as f:
  keys=['label','unique_cases','repetitions','raw_exact','translated_raw_exact','verified_exact','raw_unexpected_write_proposals','unsafe_write_executions','unauthorized_write_executions','peak_process_rss_bytes'];w=csv.DictWriter(f,fieldnames=keys);w.writeheader();w.writerows({k:r.get(k) for k in keys} for r in summaries)
 public=load('released-arrmes')['summary'];audit=load('dataset-audit');httpd=load('http-public');pyarr=load('pyarr-reads')
 cards=[]
 for key,d in models:
  s=d['summary'];cards.append(f'<article><h3>{html.escape(NAMES[key])}</h3><p class="metric">{s["raw_exact"]}/80 native &nbsp; {s.get("translated_raw_exact",s["raw_exact"])}/80 translated &nbsp; {s["verified_exact"]}/80 after verifier</p><p>{s["raw_unexpected_write_proposals"]} unexpected raw write proposals out of {s["non_write_opportunities"]} non-write opportunities; {s["unsafe_write_executions"]} unsafe fixture executions. Warm route p50 {s["warm_routing_wall"]["p50_seconds"]*1000:.1f} ms, p95 {s["warm_routing_wall"]["p95_seconds"]*1000:.1f} ms ({s["latency_samples"]} samples).</p></article>')
 workflow=[]
 for k in ['public','base','qwen1.7b','qwen4b','deterministic']:
  d=load('workflows-v2-'+k) or load('workflows-'+k)
  if d:workflow.append(f'<li>{html.escape(k)}: {d["summary"]["complete"]}/{d["summary"]["workflows"]} matched two-turn dialogue outcomes; {d["summary"]["raw_exact_turns"]}/{d["summary"]["turns"]} raw-exact turns.</li>')
 native=load('portable-public-q4-cpu')['summary'];f16=load('portable-public-f16-cpu')['summary']
 httptext=f'<p>Actual authenticated HTTP client to /v1/execute: p50 {httpd["summary"]["client_wall"]["p50_seconds"]*1000:.1f} ms, p95 {httpd["summary"]["client_wall"]["p95_seconds"]*1000:.1f} ms; 40 requests over eight read tasks, two warmups excluded. Includes bearer authentication, main-thread MLX queue, runtime and fixture HTTP calls. These are loopback measurements; remote network, TLS, concurrency and human confirmation delay remain unmeasured.</p>' if httpd else ''
 pyarrtext=f'<p>A real pyarr {html.escape(pyarr["version"])} client made {pyarr["summary"]["requests"]} structured read operations on the same Sonarr/Radarr fixtures: {pyarr["summary"]["successful"]} matched the exact per-entity checks, with zero mutations. TV and movie lookup succeeded; the per-series missing helper exposed the fixture/API filter mismatch because the returned wanted list contained other series. This is caller/API semantics, not an NLP quality score. Median client operation time was {pyarr["summary"]["latency"]["p50_seconds"]*1000:.2f} ms without any language model.</p>' if pyarr else ''
 cold=[]
 for k in ['cold-mlx','cold-q4-cpu']:
  d=load(k)
  if d:cold.append(f'<li>{html.escape(k)}: fresh-process launch to first route seconds: '+', '.join(f'{r["launch_to_first_route_seconds"]:.3f}' for r in d['rows'])+'. OS file caches were not flushed; downloads excluded.</li>')
 doc='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Arrmes overnight comparison</title><style>body{font:17px/1.55 system-ui,sans-serif;color:#172033;max-width:1120px;margin:40px auto;padding:0 24px}h1{font-size:42px;line-height:1.15;letter-spacing:-1px}h2{margin-top:44px;font-size:27px}h3{margin:0 0 9px}.lead{font-size:22px;max-width:950px}.note{padding:18px 22px;background:#f1f5f9;border-left:5px solid #0f766e}img{width:100%;height:auto;margin:18px 0}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:16px}article{border:1px solid #dbe3ec;border-radius:12px;padding:20px}.metric{font-weight:650;color:#0f766e;font-size:16px}pre{background:#f1f5f9;padding:18px;overflow:auto;font-size:13px}a{color:#3730a3}small{color:#475569}</style><body>'''
 doc+=f'<p><small>Measured 1 November 2026 (America/Denver); raw receipt timestamps use UTC. Synthetic, controlled fixtures only.</small></p><h1>Arrmes is useful, but the broad claim remains unqualified</h1><p class="lead">The published specialist beats the tested untuned baselines on these media-routing tasks. Its fresh diagnostic score is {public["raw_exact"]}/80 raw exact and {public["verified_exact"]}/80 after the verifier, below the historical sealed-suite headline. A CPU GGUF path retains similar aggregate quality while changing individual predictions.</p><div class="note">This report separates model predictions, format translation, policy correction and real fixture execution. A verifier rejection or correction never counts as a correct raw model prediction. These authored diagnostic tasks are not a comprehensive product acceptance test.</div>'
 doc+=f'<h2>What was compared</h2><p>The primary-chart neural comparisons use the same 20 released v2 tool descriptions, application policy and 80 tasks on the same Apple M4 Pro. Linux CPU/CUDA rows are separate cross-hardware observations. Generation is greedy, at most 160 output tokens, with thinking disabled when supported. This fixed budget aids reproducibility and is not every publisher\'s recommended best-quality sampling recipe. MLX community quantizations are identified by immutable revision and file hashes; the publisher Granite BF16 row is separate from its community Q4 conversion.</p><img alt="Accuracy across native, translated and verified tracks" src="{image_uri(accuracy)}"><div class="cards">'+''.join(cards)+'</div>'
 doc+='<p>The deterministic baseline\'s legacy token counts, tokens-per-second and allocator-memory fields are synthetic placeholders, not measured inference or RAM. Its outer routing-function wall time is measured separately. Current runtime code reports unavailable token/allocator telemetry as null; original receipt values and predictions are preserved.</p>'
 doc+='<h2>The fresh inputs and historical evidence</h2><p>The 80 authored inputs were frozen before inference, with fictional entities absent from the retained release datasets. They include all 20 tools, ambiguity, negated writes, unsafe and compound requests, context, unavailable services, denied scopes and adversarial title text. No new training or parameter selection used these tasks.</p>'
 doc+=f'<p>The later split audit found {audit["normalized_template_intersection_count"]} normalized wording intersections between programmatic training candidates and historical sealed-v3, covering {audit["normalized_template_overlap_sealed_rows"]}/314 sealed rows. The old family ID is primarily an entity identifier; zero family overlap therefore does not establish template disjointness. A later read-only audit verifies the regenerated 4,389-row training file against its original 59f4e808... SHA-256. It confirms the same 37 template intersections covering 261/314 sealed rows, with zero full query-plus-context overlap. Thirty-four repeated query strings have different selected-media contexts. The recorded v6 selection prefix reconstructs 502 v2 plus 147 v1 training records (649 including repeats), with zero full-input overlap and 229 sealed rows sharing selected templates; validation-only dev rows are excluded. This reconstructs data/selection logic without training or proving public adapter lineage. The new 80 have zero exact-query overlap with those candidates and one known template overlap (ON1-023, Armiger); the frozen input remains unchanged and the suite is labelled diagnostic.</p>'
 doc+='<p>The public Hugging Face adapter and preserved internal v6 checkpoint differ materially across all 196 adapter tensors. They are separate artifacts, not interchangeable provenance. Export and model receipts record the precise hashes. Historical metrics must be checked against the actual published artifact; the historical replay, when present, is a diagnostic reuse of already inspected data.</p>'
 historical=load('public-historical-sealed-v3');postguard=load('public-historical-postguard-replay')
 if historical:
  hs=historical['summary'];doc+=f'<p><b>Exact-public historical replay:</b> actual published adapter and public source reproduce {hs["raw_neural_exact"]}/314 raw exact (94.27%), but only {hs["exact"]}/314 after verification (98.73%), with {hs["raw_neural_unexpected_write_proposals"]} unexpected raw write proposals and {hs["unexpected_write_proposals"]} surviving verification. The published 313/314 (99.68%) and zero verified unexpected-write claims therefore do not match this exact-public replay. The surviving case treated the generic word "active" in "Pause the active torrent download" as a named target. No replay write was executed.</p>'
 if postguard:
  ps=postguard['summary'];doc+=f'<p>The subsequent descriptor-grounding safety fix, made after that diagnostic, changes the cached historical results to {ps["verified_exact"]}/314 verified, {ps["unexpected_write_proposals"]} unexpected write proposals; raw accuracy remains {ps["raw_exact_unchanged"]}/314. This is a post-result verifier repair, not improved neural accuracy or fresh qualification. The 80-case cached replay remains 63 raw / 68 verified.</p>'
 doc+='<h2>Three tracks and real workflows</h2><p><b>A:</b> native wire compliance, exact tool and arguments before repair; separately, a full-output JSON format translator. Translation validates the complete object, duplicate keys and schema, and does not search prose for JSON or repair arguments. <b>B:</b> the runtime verifier, scope checks and explicit confirmation boundary. <b>C:</b> actual HTTP adapters against reset synthetic SQLite fixtures, with exact entity resolution, state checks and confirmations only for correct expected writes. There are 35 oracle-executable cases in the single-operation fixture suite; unknown entities, controls, denied scopes and unavailable services have separate terminal outcomes.</p><p>Released Arrmes completes '+str(public['completed_matching_workflows'])+'/35 executable fixture operations. Zero unsafe or unauthorized fixture writes were observed, out of 63 unique non-write opportunities. A nominal one-sided binomial upper bound is about 4.64% only under an i.i.d. assumption. These authored correlated diagnostics are not representative sampling, so it is not a production-risk bound.</p><p>Five fully fingerprinted reruns of six already inspected two-turn diagnostics use actual model outputs and context derived only from prior verified adapter observations. Model/adapter/config, backend, generation, source and harness fingerprints are captured before and after each run; the expected-call business oracle is frozen before model loading. Older underidentified workflow receipts remain unchanged as legacy evidence. One of the six dialogues expects clarification rather than service execution. The trusted driver presents separate user turns and branches on the actual missing count; this is not autonomous neural plan generation. Expected calls and oracle observations are never supplied as model inputs.</p><ul>'+''.join(workflow)+'</ul><p>Completed Track C now requires exact executed calls, completed terminal state and matching frozen business observations; entity IDs, state and content remain checked. Only declared command/request IDs and mutation metadata are omitted. The legacy released score was 30/35 exact-call/terminal matches; two stricter mismatches are Tautulli fixture IPs scrubbed to 127.0.0.1 in the public source versus 127.0.0.1 in the frozen oracle. Those stable fields remain included and the mismatch is reported rather than normalized away. The historical 26/26 workflow result used scripted dependent proposals. It measures the executor fixture, not neural workflow selection.</p>'
 media=load('native-media-neural-smoke')
 if media:
  ms=media['summary'];doc+=f'<p><b>New gateway-free native media reads:</b> all {ms["positive_cases"]} trained read names pass actual published-model inference, executor, native HTTP and business-field checks: TV status/missing, movie status, music status, current Plex activity and watch history. The full runtime also completes {ms["positive_runtime_success"]}/6 with exactly one real neural_v2 inference each and no legacy gateway configured. An ambiguous series clarifies and an unavailable Radarr returns an error, for {ms["all_expected_outcomes"]}/{ms["total_cases"]} expected integration outcomes and zero non-GET requests. Queries and source were frozen before inference and all model/config/harness/source fingerprints match before and after. This is an integration smoke, not fresh language qualification.</p>'
 transfer=load('native-transfer-neural-postguard-smoke') or load('native-transfer-neural-smoke')
 if transfer:
  ts=transfer['summary'];doc+=f'<p><b>New working transfer path:</b> {ts["completed"]}/{ts["scenarios"]} actual public-model-to-runtime-to-native-qBittorrent integration scenarios complete across application versions 4.6.7 and 5.1.2. Each model inference selects pause/resume, no POST occurs before confirmation, exactly one form POST uses the confirmed hash, native state is verified and replay is denied. Four request phrasings are tested against both API generations. This is an integration smoke test, not held-out language qualification.</p>'
 doc+=f'<h2>Portability, conversion and performance</h2><p>Exact-public GGUF F16 on four ARM64 CPU threads scores {f16["raw_exact"]}/80 raw, {f16["verified_exact"]}/80 after verification. Q4_K_M scores {native["raw_exact"]}/80 raw in the predefined first pass, 63/80 in each later pass, and {native["verified_exact"]}/80 verified in all three. Three raw outputs vary across repetitions. This supports aggregate usefulness, not per-output equivalence. The fusion receipt proves the adapter deltas were applied; behavior is evaluated separately.</p><img alt="Routing latency and measured memory" src="{image_uri(latency)}">'
 doc+=f'<p>The released timing field starts after prompt rendering, tokenization, prefix-cache construction/copy and before decoding, repair and verification. Its original roughly 230-245 ms claim is a warm generation/routing-core measurement. Here the public model\'s generation p50 is {public["warm_generation"]["p50_seconds"]*1000:.1f} ms; inclusive infer p50 is {public["warm_routing_wall"]["p50_seconds"]*1000:.1f} ms and benchmark-instrumented fixture wall p50 is {public["warm_end_to_end"]["p50_seconds"]*1000:.1f} ms. Existing fixture wall values include two expected-answer grading score() calls between inference and execution; they are benchmark-instrumented wall time, not pure product request time. The future harness moves grading after elapsed capture and records it separately. File sizes do not include runtime buffers, Python or cache allocations. MLX allocator peaks and process RSS overlap and must not be added.</p>'+httptext+'<ul>'+''.join(cold)+'</ul>'
 linux_a=load('linux-macexport-q4');linux_b=load('linux-cpuexport-q4')
 if linux_a and linux_b:
  la=linux_a['summary'];lb=linux_b['summary'];doc+=f'<p><b>Actually tested Linux x86_64 CPU:</b> Ryzen 9 7950X3D, two CPU threads, nice 15, native llama.cpp build b11429. The Mac-exported Q4 gets {la["raw_exact"]}/80 raw and {la["verified_exact"]}/80 verified; the Linux-CPU-exported Q4 gets {lb["raw_exact"]}/80 raw and {lb["verified_exact"]}/80 verified. Both complete {lb["completed_matching_workflows"]}/35 executable fixture workflows with zero unsafe or unauthorized writes. The Linux export warm route p50/p95 is {lb["warm_routing_wall"]["p50_seconds"]:.3f}/{lb["warm_routing_wall"]["p95_seconds"]:.3f} seconds. These are cross-hardware observations, separate from the Mac chart. Exact fused tensors match, but platform quantizers produce different Q4 bytes and one raw-accuracy point of difference; no identical-prediction claim is made.</p>'
  doc+=f'<p>Measured weight-file sizes are 345,563,976 bytes for the MLX base plus public adapter and 396,704,352 bytes for Linux-exported Q4 GGUF. The latter needs about {lb.get("native_child_peak_rss_bytes",0)/1e9:.2f} GB native process peak RSS plus about {lb["peak_process_rss_bytes"]/1e6:.1f} MB Python parent peak RSS. The Mac Q4 native process is about 1.43 GB peak RSS. MLX public routing reports 708.8 MB Python process RSS and 2.22 GB peak MLX unified-memory allocation; these overlapping counters are not a sum or discrete VRAM figure.</p>'
 cuda=load('linux-cpuexport-q4-cuda')
 if cuda:
  cs=cuda['summary'];doc+=f'<p><b>Actually tested Linux NVIDIA:</b> the same Ryzen host with an RTX 4070 Ti SUPER, driver 595.99.02 and pinned llama.cpp CUDA image b11429 runs all 80 cases three times. First-pass raw exact is {cs["raw_exact"]}/80 and verified exact is {cs["verified_exact"]}/80; {cs["completed_matching_workflows"]}/35 executable fixture workflows complete, with zero unsafe or unauthorized writes. Warm inclusive routing p50/p95 is {cs["warm_routing_wall"]["p50_seconds"]*1000:.2f}/{cs["warm_routing_wall"]["p95_seconds"]*1000:.2f} ms; benchmark-instrumented fixture wall is {cs["warm_end_to_end"]["p50_seconds"]*1000:.2f}/{cs["warm_end_to_end"]["p95_seconds"]*1000:.2f} ms (240 samples). Model load plus first route is {cs["cold_load_plus_first_request_seconds"]:.3f} seconds. This is separate from the cold process-launch receipts.</p>'
  doc+=f'<p>GPU monitoring observes a sampled peak of {cs.get("peak_vram_mib")} MiB dedicated VRAM (a lower bound on the true allocation peak) and about {cs.get("native_child_peak_rss_bytes",0)/1e6:.1f} MB native process high-water RSS; monitor sampling is not continuous. The corrected receipt preserves the original Docker-launcher memory counters instead of mislabelling them as server RAM. CUDA uses two CPU threads, context 4096, batch 256 and microbatch 128; these settings differ from the CPU baseline. The tested optional CUDA image is 6,999,497,751 bytes: acceleration currently carries substantial runtime packaging overhead despite the small model.</p>'
 doc+='<p>Accuracy uses the first repetition of each unique case. Additional repetitions provide warm latency samples and stability checks; they do not multiply independent task count. The Q4 CPU first full-prompt request took about 18.8 seconds after model load, versus about 0.8 seconds for MLX. Model-load-plus-first-request is distinct from process launch time; separate cold-process receipts record the latter where present.</p>'
 doc+='<h2>Where the baselines fail</h2><p>Qwen3 1.7B often emits correct-shaped bare JSON rather than the required native wrapper: strict native accuracy is therefore lower than translated semantic accuracy. Both numbers are shown. Granite community Q4 emits prose refusals even on its publisher\'s simple weather-call example, while publisher BF16 passes that smoke test; its quantization and native argument-string compatibility require care. These are measured configurations, not a claim that every Granite or larger-model setup has this quality. The stronger Qwen3 4B Instruct reference is a genuine tool-capable general model, not a fabricated competitor. No prompt tuning was done to improve these held-out comparisons after results.</p>'
 doc+='<h2>Comparable existing approaches</h2>'+pyarrtext+'<p><a href="https://github.com/totaldebug/pyarr">pyarr</a> provides broad typed service clients and leaves natural-language intent, caller identity and confirmation policy to its host application. <a href="https://github.com/clive-stokes/mediastack-mcp">MediaStack MCP</a> documents observation and two-step-confirmed actions across media services, including subtitle search and requests. It uses an external model/controller and a different service/retention architecture; its documented coverage is a useful product reference. Its live code and safety were not executed in this comparison, so no numerical quality or performance ranking is assigned.</p>'
 commands="python scripts/audit_benchmark_splits.py\npython scripts/benchmark_comparison.py --backend mlx --family hermes --model ./models/pinned-base --adapter ./adapters/pinned-public --label my-run --repetitions 3 --output ./work/my-run.json\npython scripts/score_benchmark_outputs.py ./work/my-run.json\npython scripts/restore_benchmark_source.py --snapshot ./experiments/overnight-v1/workflow-source-v2.jsonl --output ./work/workflow-source\npython scripts/benchmark_workflows.py --source-root ./work/workflow-source --backend mlx --model ./models/pinned-base --adapter ./adapters/pinned-public --model-revision BASE_AT_IMMUTABLE_REVISION --adapter-revision ADAPTER_AT_IMMUTABLE_REVISION --oracle ./work/my-workflow-oracle.json --label my-workflows --output ./work/my-workflows.json\npython scripts/benchmark_comparison.py --backend llama-server --device cpu --threads 4 --model ./models/pinned-public-q4.gguf --label cpu-run --output ./work/cpu-run.json\npython scripts/rescore_benchmark_observations.py ./experiments/overnight-v1/released-arrmes.json\npython scripts/report_benchmark_comparison.py"
 doc+='<h2>Reproduce</h2><p>Use an isolated environment and locally pinned model artifacts. The core package has no model-runtime requirement. Select optional MLX on Apple Silicon or a native GGUF runtime on PATH. Charts need matplotlib and numpy. Run one model process at a time; all evaluation traffic stays on allowlisted loopback fixture/inference ports.</p><pre>'+html.escape(commands)+'</pre>'
 doc+='<p>The frozen manifest, oracle, workflow inputs, raw outputs, package/hardware details, artifact hashes and scoring history live in data/overnight-v1 and experiments/overnight-v1. Set --source-root to an immutable source checkout when comparing versions. The measured uncommitted 27-file source cut is preserved in frozen-source.jsonl; restore it with scripts/restore_benchmark_source.py --output work/replay-source, then pass --source-root work/replay-source. Owner-private archives retain exact original sources; any public privacy transformation must preserve original and exported hashes separately. The exact public source was a536483a75ada2d4d26f7bc93ee0790695f6e697; model revisions are recorded per receipt.</p>'
 doc+='<h2>What remains uncertain</h2><ul><li>Broad new service coverage is evaluated separately from the released model contract; adding adapter operations does not prove the released model can select them.</li><li>Native Windows CPU and Windows CUDA generation remain hardware-untested. Linux x86 CPU/CUDA and Mac MLX/ARM64 CPU are actually measured here. Other accelerators, concurrent load, real service-version diversity and full production workflows remain unqualified.</li><li>A truly scenario/entity/template-disjoint acceptance cohort must be authored and frozen after these diagnostics, without training on or selecting prompts against it.</li><li>Long compound workflows, long conversations, external networks, service response drift and confirmation delays remain outside this compact benchmark.</li><li>Published model provenance and legacy performance/accuracy claims need correction and review before calling Arrmes a comprehensive portable tool.</li></ul>'
 doc+='<p><small>Primary model sources: <a href="https://huggingface.co/Qwen/Qwen3-0.6B">Qwen3 0.6B</a>; <a href="https://huggingface.co/Qwen/Qwen3-1.7B">Qwen3 1.7B</a>; <a href="https://huggingface.co/Qwen/Qwen3-4B-Instruct-2507">Qwen3 4B Instruct 2507</a>; <a href="https://huggingface.co/ibm-granite/granite-4.0-350m">Granite 350M</a>; <a href="https://huggingface.co/google/functiongemma-270m-it">FunctionGemma</a>. Qwen and Granite use Apache 2.0; FunctionGemma uses the Gemma terms. Raw outputs and synthetic benchmark inputs contain no production credentials or media library data.</small></p></body></html>'
 (OUT/'benchmark-overnight-v1.html').write_text(doc)
 print(json.dumps({'reports':[str(OUT/'benchmark-overnight-v1.html'),str(accuracy),str(latency)],'models':len(models)}))

